800					// Checkout every one of the referenced sources to the target revision before generating Manifests
801					for _, valueFile := range refCandidates {
802						if !strings.HasPrefix(valueFile, "$") {
803							continue
804						}
805						refVar := strings.Split(valueFile, "/")[0]
806	
807						refSourceMapping, ok := q.RefSources[refVar]
808						if !ok {
809							if len(q.RefSources) == 0 {
810								ch.errCh <- fmt.Errorf("source referenced %q, but no source has a 'ref' field defined", refVar)
811							}
812							refKeys := make([]string, 0)
