20	// Lock acquires lock unless lock is already acquired with the same commit and allowConcurrent is set to true
21	// The init callback receives `clean` parameter which indicates if repo state must be cleaned after running non-concurrent operation.
22	// The first init always runs with `clean` set to true because we cannot be sure about initial repo state.
23	func (r *repositoryLock) Lock(path string, revision string, allowConcurrent bool, init func(clean bool) (io.Closer, error)) (io.Closer, error) {
24		r.lock.Lock()
25		state, ok := r.stateByKey[path]
26		if !ok {
27			state = &repositoryState{cond: &sync.Cond{L: &sync.Mutex{}}}
28			r.stateByKey[path] = state
29		}
30		r.lock.Unlock()
31	
32		closer := utilio.NewCloser(func() error {
33			state.cond.L.Lock()
34			notify := false
35			state.processCount--
36			var err error
37			if state.processCount == 0 {
38				notify = true
39				state.revision = ""
40				err = state.initCloser.Close()
41			}
42	
43			state.cond.L.Unlock()
44			if notify {
45				state.cond.Broadcast()
46			}
47			if err != nil {
48				return fmt.Errorf("init closer failed: %w", err)
49			}
50			return nil
51		})
52	
53		for {
54			state.cond.L.Lock()
55			if state.revision == "" {
56				// no in progress operation for that repo. Go ahead.
57				initCloser, err := init(!state.allowConcurrent)
58				if err != nil {
59					state.cond.L.Unlock()
60					return nil, fmt.Errorf("failed to initialize repository resources: %w", err)
61				}
62				state.initCloser = initCloser
63				state.revision = revision
64				state.processCount = 1
65				state.allowConcurrent = allowConcurrent
66				state.cond.L.Unlock()
67				return closer, nil
68			} else if state.revision == revision && state.allowConcurrent && allowConcurrent {
69				// same revision already processing and concurrent processing allowed. Increment process count and go ahead.
70				state.processCount++
71				state.cond.L.Unlock()
72				return closer, nil
73			}
74			state.cond.Wait()
75			// wait when all in-flight processes of this revision complete and try again
76			state.cond.L.Unlock()
77		}
78	}
